from typing import Set, TypeVar, Generic

T = TypeVar('T')

class GSet(Generic[T]):
    """
    A Grow-only Set (G-Set) CRDT.
    Elements can only be added, never removed.
    """
    def __init__(self, initial_elements: Set[T] = None):
        self._elements = initial_elements if initial_elements is not None else set()

    def add(self, element: T):
        """
        Adds an element to the set.
        """
        self._elements.add(element)

    def merge(self, other_set: 'GSet[T]') -> 'GSet[T]':
        """
        Merges this G-Set with another G-Set.
        The merged set contains all elements from both sets.
        """
        merged_elements = self._elements.union(other_set._elements)
        return GSet(merged_elements)

    def lookup(self) -> Set[T]:
        """
        Returns all elements currently in the set.
        """
        return self._elements

    def __contains__(self, element: T) -> bool:
        return element in self._elements

    def __len__(self) -> int:
        return len(self._elements)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, GSet):
            return NotImplemented
        return self._elements == other._elements

    def __repr__(self) -> str:
        return f"GSet({self._elements})"
